-- Copiar faturamentos da Mascote (tenant 1 → tenant 60002)
INSERT INTO faturamentos (empresaSlug, data, cat1, cat2, cat3, cat4, cat5, observacao, lancadoPor, createdAt, updatedAt, tenantId)
SELECT empresaSlug, data, cat1, cat2, cat3, cat4, cat5, observacao, lancadoPor, createdAt, updatedAt, 60002
FROM faturamentos
WHERE tenantId = 1 AND empresaSlug = 'MASCOTE';

-- Copiar metas da Mascote (tenant 1 → tenant 60002)
INSERT INTO metas (empresa, mes, ano, metaMensal, metaQuinzenal, createdAt, updatedAt, diasUteis, diasUteisQuinzenal, empresaSlug, tenantId)
SELECT empresa, mes, ano, metaMensal, metaQuinzenal, createdAt, updatedAt, diasUteis, diasUteisQuinzenal, empresaSlug, 60002
FROM metas
WHERE tenantId = 1 AND empresaSlug = 'MASCOTE';

-- Verificar resultado
SELECT COUNT(*) as faturamentos_copiados FROM faturamentos WHERE tenantId = 60002;
SELECT COUNT(*) as metas_copiadas FROM metas WHERE tenantId = 60002;
